// Sound-effect cue sheet. Files live in public/audio/<name>.wav
// (generated by scripts/make_audio.py). `at` is in frames local to the scene.
import { Audio } from "@remotion/media";
import React from "react";
import { Sequence, staticFile } from "remotion";

export type SfxName =
  | "whoosh" | "whoosh_soft" | "hit" | "tap" | "sonar" | "found" | "success"
  | "beep_normal" | "beep_warn" | "beep_crit" | "alert_warn" | "alert_crit"
  | "step" | "pop_open" | "pop_close" | "msg_in" | "msg_out" | "typing"
  | "confused" | "scared" | "laugh" | "sparkle"
  | "swap1" | "swap2" | "swap3" | "swap4" | "swap5" | "swap6" | "close";

export type Cue = { at: number; name: SfxName; volume?: number };

/** Default mix levels, so every scene sits at the same loudness. */
export const LEVEL = { ui: 0.5, character: 0.55, monitor: 0.35, alert: 0.5, transition: 0.3, impact: 0.7 };

export const Sfx: React.FC<{ cues: Cue[] }> = ({ cues }) => (
  <>
    {cues
      .filter((c) => c.at >= 0)
      .map((c, i) => (
        <Sequence key={`${c.name}-${c.at}-${i}`} from={Math.round(c.at)} layout="none" name={`sfx ${c.name}`}>
          <Audio src={staticFile(`audio/${c.name}.wav`)} volume={c.volume ?? LEVEL.ui} />
        </Sequence>
      ))}
  </>
);
